// Turn every PDF attachment into its own item so each RFP PDF is processed separately
const out = [];
for (const item of $input.all()) {
  for (const [key, bin] of Object.entries(item.binary || {})) {
    const isPdf = bin.mimeType === 'application/pdf' || (bin.fileName || '').toLowerCase().endsWith('.pdf');
    if (isPdf) {
      out.push({
        json: {
          messageId: item.json.id,
          subject: item.json.subject,
          fileName: bin.fileName
        },
        binary: { data: bin }
      });
    }
  }
}
if (out.length === 0) {
  throw new Error('No PDF attachments found in this email');
}
return out;

const MAX_CHARS = 10000;
return $input.all().map(item => {
  let text = (item.json.text || '').toString();
  if (!text.trim()) throw new Error('PDF text extraction returned nothing');

  // start at the scope/requirements section, skipping schedule and submission rules
  const s = text.search(/scope of (professional )?(work|services?)|statement of work|project description/i);
  let body = s > 0 ? text.slice(s) : text;

  // stop before proposal-format, legal and evaluation boilerplate
  const e = body.search(/proposal requirements|statement of rights|evaluation criteria|indemnification/i);
  if (e > 500) body = body.slice(0, e);

  return { json: { ...item.json, text: body.slice(0, MAX_CHARS), truncated: body.length > MAX_CHARS } };
});

const FIB = [1, 2, 3, 5, 8, 13, 21];
const snap = n => FIB.reduce((a, b) => Math.abs(b - n) < Math.abs(a - n) ? b : a);

const rows = [];
for (const item of $input.all()) {
  const out = item.json.output;
  const raw = typeof out === 'string' ? out : JSON.stringify(out);
  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('No JSON found: ' + raw.slice(0, 300));

  let parsed;
  try {
    parsed = JSON.parse(raw.slice(start, end + 1));
  } catch (e) {
    throw new Error('Invalid JSON from model (maybe cut off): ' + raw.slice(-300));
  }
  if (!Array.isArray(parsed.modules) || parsed.modules.length === 0) {
    throw new Error('No modules returned by the AI');
  }

  const metadata = parsed.project_metadata || {};
  const architecture = parsed.technical_architecture || {};
  const governance = parsed.project_governance || {};

  for (const mod of parsed.modules) {
    rows.push({
      json: {
        project_title: metadata.project_title || 'Untitled Project',
        primary_objective: metadata.primary_objective || '',
        tech_stack: Array.isArray(architecture.suggested_tech_stack) ? architecture.suggested_tech_stack.join(', ') : '',
        module_name: mod.module_name || '',
        module_description: mod.module_description || '',
        user_stories: Array.isArray(mod.core_user_stories) ? mod.core_user_stories.join(' | ') : '',
        estimated_story_points: snap(Number(mod.estimated_story_points) || 0),
        complexity_rationale: mod.complexity_rationale || '',
        key_assumptions: Array.isArray(governance.key_assumptions) ? governance.key_assumptions.join(' | ') : '',
        high_risk_factors: Array.isArray(governance.high_risk_factors) ? governance.high_risk_factors.join(' | ') : ''
      }
    });
  }
}
return rows;
